import os
import re
from robot.api import logger as robot_logger
from taf.ul.ettf.logger.logger import custom_logger
from taf.ul.ettf.utils.paths import get_robot_output_dir
from jinja2 import Environment, FileSystemLoader


logger = custom_logger('Reporter')
TEMPLATE_DIRECTORY = os.path.dirname(__file__)
TEMPLATE_FILE_NAME = 'template.html'


class Reporter(object):
    def __call__(self, analyzed_results):
        pass

    def _condition_meet(self, analyzed_results):
        return analyzed_results.anything_to_report


class LoggingReporter(Reporter):
    def __init__(self, logger_call, max_logged_lines=None, strip_lines=False):
        self._logger_call = logger_call
        self._max_logged_lines = max_logged_lines
        self._strip_lines = strip_lines

    def __call__(self, analyzed_results):
        if self._condition_meet(analyzed_results):
            for analyzed_result in analyzed_results:
                self._logger_call('Found in {} (triggered by: {}):\n'.format(analyzed_result.analyzed_path, analyzed_result.trigger))
                self._log_lines(analyzed_result)

    def _log_lines(self, analyzed_result):
        for lines in analyzed_result.data.values():
            for line in lines[:self._max_logged_lines]:
                self._logger_call('\t{}'.format(line.strip() if self._strip_lines else line))
            if self._max_logged_lines and len(lines) > self._max_logged_lines:
                self._logger_call('\t...')


class LogToConsoleAndHtml(LoggingReporter):
    def __init__(self):
        super(LogToConsoleAndHtml, self).__init__(robot_logger.error, max_logged_lines=3, strip_lines=True)


class LogToFile(Reporter):
    def __init__(self, file_path=None, file_name='log_analysis.log'):
        self._file_name = file_name
        self._file_path = file_path if file_path else os.path.join(get_robot_output_dir(), self._file_name)

    def __call__(self, analyzed_results):
        if self._condition_meet(analyzed_results):
            with open(self._file_path, 'a') as f:
                LoggingReporter(f.write)(analyzed_results)
                robot_logger.info('Full analysis result can be found in {}'.format(self._file_path))


class PrettyHtmlReporter(LogToFile):
    def __init__(self, file_path=None, file_name='log_analysis.html', max_logged_lines=10):
        super(PrettyHtmlReporter, self).__init__(file_path, file_name)
        self._max_logged_lines = max_logged_lines

    def __call__(self, analyzed_results):
        if self._condition_meet(analyzed_results):
            table = self._create_table(analyzed_results)
            self._save_to_log_html(table)
            self._save_to_file(table)

    def _create_table(self, analyzed_results):
        environment = Environment(loader=FileSystemLoader(TEMPLATE_DIRECTORY))
        template = environment.get_template(TEMPLATE_FILE_NAME)
        return template.render(results=analyzed_results, max_lines=self._max_logged_lines)

    def _save_to_log_html(self, table):
        robot_logger.info(self._fix_white_chars(table), html=True)

    def _save_to_file(self, html):
        with open(self._file_path, 'a') as result:
            result.write(html)
        robot_logger.info('Html analysis result can also be found in {}'.format(self._file_path))

    @staticmethod
    def _fix_white_chars(string):
        string = re.sub(r'^\s+', '', string)
        return re.sub(r'\s+', ' ', string)
